Here's a custom React hook for handling local storage with expiration support:

```javascript
import { useState, useCallback } from 'react';

function useLocalStorage(key, initialValue, ttl = null) {
    // ttl: time to live in milliseconds (null = never expires)

    const [storedValue, setStoredValue] = useState(() => {
        try {
            const item = window.localStorage.getItem(key);
            if (item === null) return initialValue;

            const parsed = JSON.parse(item);

            // Check expiration
            if (parsed.expiry && Date.now() > parsed.expiry) {
                window.localStorage.removeItem(key);
                return initialValue;
            }

            return parsed.value;
        } catch (error) {
            console.warn('Error reading localStorage:', error);
            return initialValue;
        }
    });

    const setValue = useCallback((value) => {
        try {
            const valueToStore = value instanceof Function ? value(storedValue) : value;
            const item = {
                value: valueToStore,
                expiry: ttl ? Date.now() + ttl : null,
            };
            setStoredValue(valueToStore);
            window.localStorage.setItem(key, JSON.stringify(item));
        } catch (error) {
            console.warn('Error setting localStorage:', error);
        }
    }, [key, storedValue, ttl]);

    const remove = useCallback(() => {
        try {
            window.localStorage.removeItem(key);
            setStoredValue(initialValue);
        } catch (error) {
            console.warn('Error removing localStorage:', error);
        }
    }, [key, initialValue]);

    return [storedValue, setValue, remove];
}

export default useLocalStorage;

// Usage with 1-hour expiration:
// const [token, setToken] = useLocalStorage('auth_token', null, 3600000);
// const [theme, setTheme] = useLocalStorage('theme', 'light');
// const [preferences, setPreferences, clearPrefs] = useLocalStorage('prefs', {});
```

This hook adds a time-to-live feature: data automatically expires after the specified duration. It stores both the value and expiry timestamp in JSON format and checks expiration on every read.
